// A role you applied to has come off its board. This is the whole reason the project exists:
// no board announces a filled role, so without this you keep waiting on something that ended.
// Matching is by URL, which is the only field both sides genuinely share.
const closed = items.map(i => i.json).filter(p => p.status === 'closed');
const apps = $('Get applications').all().map(i => i.json);

const norm = u => (u || '').trim().replace(/\/+$/, '').toLowerCase();
const appliedTo = new Map();
for (const a of apps) {
  if (a.url && a.status === 'applied') appliedTo.set(norm(a.url), a);
}

const hits = [];
for (const p of closed) {
  const a = appliedTo.get(norm(p.url));
  if (a) hits.push({ company: a.company, role: a.role, closed_at: p.closed_at });
}
if (!hits.length) return [];

const lines = hits.map(h => `• **${h.company}** — ${h.role}`);
const content = [
  `**${hits.length} role${hits.length > 1 ? 's' : ''} you applied to closed**`,
  ...lines,
  '_Stop waiting on these._',
].join('\n');

return [{ json: { content } }];
